        q: 'What is the difference between split-thickness and full-thickness skin grafting?',
        a: 'A split-thickness skin graft (STSG) involves harvesting the top layer of skin (epidermis) and a thin portion of the dermis, typically from the thigh. It takes rapidly and is ideal for covering large burn surfaces. A full-thickness skin graft (FTSG) includes the entire epidermis and dermis, harvested from areas with loose skin like the groin or supraclavicular region. FTSGs are primarily used on cosmetically sensitive areas like the face, eyelids, and hands because they resist shrinkage and provide a superior texture match.',
