        q: 'What is a propeller perforator flap in trauma surgery?',
        a: 'A propeller flap is an advanced reconstructive technique where a segment of healthy skin and fascia adjacent to the wound is isolated on a single microscopic nutrient blood vessel (perforator). The flap is then rotated up to 180 degrees like an airplane propeller to cover the exposed bone or tendon defect, providing perfect matching tissue coverage without needing to sacrifice any of the leg’s main blood vessels.',
