        q: 'Do titanium mini-plates used in facial fracture surgery need to be removed later?',
        a: 'In the vast majority of patients, no. The titanium mini-plates and micro-screws used by Dr. Chintan Gujarathi are made of medical-grade, highly biocompatible titanium that integrates harmlessly with facial bone. They are non-magnetic, will not trigger airport security metal detectors, and are safe for future MRI or CT scans. They only need to be removed in the rare event of late infection or if a patient specifically prefers them taken out after bone healing is complete.',
