    faqs: [
      {
        q: 'Why does a sebaceous cyst recur if it is just squeezed or drained?',
        a: 'A sebaceous (epidermoid) cyst consists of an outer epithelial sac or capsule filled with cheesy keratin material. When a cyst is squeezed, popped, or simply drained with a needle, only the contents are evacuated, while the inner sac remains intact. The remaining lining cells immediately begin producing keratin again, leading to prompt recurrence, often with secondary infection. Complete, permanent cure requires surgical excision of the entire capsule intact, which is Dr. Gujarathi’s standard technique.',
      },
      {
        q: 'How much does cyst, lipoma, or ganglion excision cost in Pune?',
        a: 'The cost of minor dermatosurgical excision in Pune generally ranges from ₹8,000 to ₹18,000 for a small to moderate sebaceous cyst, wart, or lipoma under local anesthesia as an outpatient day-care procedure. Multiple lipomas, large deep lipomas, or complex wrist ganglion stalk resections adjacent to the radial artery typically range from ₹18,000 to ₹35,000 at Ruby Hall Clinic and Manipal Hospital Kharadi. All charges include routine formal histopathology biopsy examination.',
      },
      {
        q: 'Will the surgical removal leave an obvious scar?',
        a: 'Because Dr. Chintan Gujarathi is an MCh Plastic Surgeon, minimizing scars is a primary consideration. Incisions are made strictly along relaxed skin tension lines (Langer’s lines) or hidden in natural anatomical folds. Incisions are kept as small as possible (minimal incision technique), and closure is performed using buried intradermal sutures with fine cosmetic materials. After healing, the incision fades into a discreet hairline mark that is virtually invisible.',
      },
      {
        q: 'Can a wrist ganglion be treated with aspiration instead of surgery?',
        a: 'Aspiration (drawing out the jelly-like fluid with a syringe) can provide temporary relief, but has a very high recurrence rate of 50% to 70% because the connection (stalk) to the wrist joint remains open. Complete surgical excision under magnification involves following the stalk down to its origin in the scapholunate joint capsule and removing the base stalk, which reduces recurrence to less than 5%.',
      },
      {
        q: 'Can I go back to work immediately after cyst or lipoma removal?',
        a: 'Yes. Excision of cysts, lipomas, and ganglions is performed under gentle local anesthesia as a day-care procedure, taking approximately 20 to 30 minutes. You can walk out of the clinic and return to desk work, driving, and light daily activities immediately. A waterproof dressing is placed over the incision so you can shower normally without wetting the stitches.',
      },
    ],
