        q: 'Are dermal filler injections painful and will I have bruises?',
        a: 'The treatment is remarkably comfortable. Dr. Gujarathi applies a prescription topical numbing cream prior to injection, and the filler gel itself contains integrated lidocaine local anesthetic that numbs the area as it is placed. Furthermore, by utilizing a blunt-tipped flexible micro-cannula rather than sharp needles, the cannula glides gently around nerves and blood vessels without cutting them, which reduces bruising to near zero in the vast majority of patients.',
