    faqs: [
      {
        q: 'Will having a sural nerve biopsy make my foot or leg weak?',
        a: 'No. The sural nerve is a purely sensory nerve located behind the outer ankle bone (lateral malleolus). It supplies sensation to a small patch of skin along the outer edge of your foot and heel, but has absolutely zero motor fibers controlling movement. Harvesting a 2 to 3 cm segment does not affect your ability to walk, run, or move your foot in any way. While a patch of skin on the side of your foot will feel numb initially, this area naturally shrinks over time.',
      },
      {
        q: 'How much does peripheral nerve surgery and nerve biopsy cost in Pune?',
        a: 'In Pune, diagnostic sural nerve and muscle biopsy typically ranges from ₹18,000 to ₹35,000 as a day-care procedure under local anesthesia. Microsurgical enucleation of a peripheral schwannoma or neuroma ranges from ₹30,000 to ₹65,000 depending on the size and nerve location. Traumatic microsurgical nerve repair or nerve grafting ranges from ₹35,000 to ₹85,000 at Ruby Hall Clinic and Manipal Hospital Kharadi, commonly covered by medical insurance.',
      },
      {
        q: 'What is a schwannoma and is it dangerous or cancerous?',
        a: 'A schwannoma (neurilemoma) is an overwhelmingly benign, slow-growing tumor originating from Schwann cells that insulate peripheral nerves. It is not cancerous and does not spread to other organs. However, as it enlarges inside the tight nerve sheath, it compresses adjacent healthy nerve fibers, causing pain, electric tingling, or numbness. Dr. Gujarathi uses an operating microscope to carefully shell out the schwannoma from within its capsule, curing the tumor permanently without cutting functioning nerve fibers.',
      },
      {
        q: 'How fast do damaged nerves heal and regrow after microsurgery?',
        a: 'After a nerve is cleanly repaired or grafted under a microscope, the axons from the proximal stump regrow through the protective epineural sheath toward their target muscles or sensory receptors at an average rate of approximately 1 millimeter per day (about 1 inch per month). A nerve injury in the forearm may take 6 to 12 months for sensation to travel all the way into the fingertips.',
      },
      {
        q: 'Can Morton’s neuroma in the foot be treated with plastic surgery?',
        a: 'Yes. Morton’s neuroma is a painful, thickened fibrotic swelling of the interdigital nerve between the third and fourth toes, often caused by repetitive friction and narrow footwear. If conservative pads and injections fail, Dr. Gujarathi performs a microscopic excision through a small hidden dorsal incision. This permanently relieves the severe "walking on a burning marble" pain, allowing patients to walk comfortably.',
      },
    ],
